#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn async_request_without_storage_is_unavailable() {
    // No storage backend is configured in the test harness, so an async export
    // has nowhere to land and is refused with 503 rather than accepted.
    let rows = [serde_json::json!({ "fields": { "name": "Ada", "notes": "n" } })];
    let state = seeded_state(export_schema(), &rows).await;
    let app = app_with_claims(state, make_claims(&["platform_admin"]));

    let (status, json) = raw_request(
        &app,
        Method::POST,
        "/schemas/Subject/entities/export",
        Some(serde_json::json!({ "format": "csv", "async": true })),
    )
    .await;

    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "body: {json}");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn status_for_unknown_job_is_not_found() {
    let rows = [serde_json::json!({ "fields": { "name": "Ada", "notes": "n" } })];
    let state = seeded_state(export_schema(), &rows).await;
    let app = app_with_claims(state, make_claims(&["platform_admin"]));

    let (status, json) = raw_request(
        &app,
        Method::GET,
        "/schemas/Subject/exports/exp_does_not_exist",
        None,
    )
    .await;

    assert_eq!(status, StatusCode::NOT_FOUND, "body: {json}");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn status_on_non_export_schema_is_forbidden() {
    // A schema with no @export must refuse status lookups, fail-closed, even
    // though the job id is unknown — the export gate runs before the lookup.
    let schema = SchemaDefinition::new(
        SchemaId::new(),
        SchemaName::new("Locked").unwrap(),
        vec![exportable_field("name")],
        vec![Annotation::Access {
            read: vec!["analyst".to_string()],
            write: vec!["analyst".to_string()],
            delete: vec![],
            cross_tenant_read: vec![],
        }],
    )
    .unwrap();
    let state = seeded_state(schema, &[]).await;
    let app = app_with_claims(state, make_claims(&["platform_admin"]));

    let (status, json) = raw_request(
        &app,
        Method::GET,
        "/schemas/Locked/exports/exp_anything",
        None,
    )
    .await;

    assert_eq!(status, StatusCode::FORBIDDEN, "body: {json}");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn status_endpoint_returns_completed_job_with_download_url() {
    // Drive a job to completion through the actor with a mock store, register it
    // under a known id, then read it back through the HTTP status route.
    let rows = [serde_json::json!({ "fields": { "name": "Ada", "notes": "n" } })];
    let state = seeded_state(export_schema(), &rows).await;
    let (forge, schema_def, policy_store, tenant_config, record_access_policy) =
        job_inputs(&state, "Subject").await;
    let job_actor = state.actor::<ExportJobActor>().expect("ExportJobActor").clone();

    let store = Arc::new(MockStore::default());
    let job_id = schema_forge_acton::export_job::new_job_id();
    let object_key = format!("exports/Subject/{job_id}.ndjson");
    let spec = ExportJobSpec {
        job_id: job_id.clone(),
        schema_name: "Subject".into(),
        schema_def,
        format: ExportFormat::Ndjson,
        filter: None,
        fields: None,
        max_rows: 100,
        claims: Some(make_claims(&["platform_admin"])),
        tenant_config,
        policy_store,
        record_access_policy,
        forge,
        store,
        object_key,
        audit_logger: None,
        subject: None,
    };
    job_actor.send(StartExportJob::new(spec)).await;
    let record = poll_until_terminal(&job_actor, &job_id).await;
    assert_eq!(record.status, ExportJobStatus::Complete);

    let app = app_with_claims(state, make_claims(&["platform_admin"]));
    let (status, json) = raw_request(
        &app,
        Method::GET,
        &format!("/schemas/Subject/exports/{job_id}"),
        None,
    )
    .await;

    assert_eq!(status, StatusCode::OK, "body: {json}");
    assert_eq!(json["status"], "complete");
    assert_eq!(json["job_id"], job_id);
    assert!(json["download_url"].as_str().unwrap().starts_with("https://mock.example/"));
}
